package com.muxigame.city;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsFamilyBudget {
 @GameTest(template="empty") public static void budgetCarrySurvivesReloadAndLegacyData(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var family=f.r.state.families.values().iterator().next();var p=FamilyBudget.policy(f.s,family);p.day=17;p.opening=300;p.surplus=1.25;p.allowance=7.75;p.spent=2;p.used=3;var tag=f.t.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var copy=CityTrade.load(tag,h.getLevel().registryAccess());var q=copy.state.familyBudgets.get(family.id);h.assertTrue(q.day==17&&q.opening==300&&q.surplus==1.25&&q.allowance==7.75&&q.spent==2&&q.used==3,"Fractional budget and actual cash accounting persist without generating money");var old=CityEconomy.JSON.toJsonTree(f.t.state).getAsJsonObject();old.remove("familyBudgets");tag.putByteArray("Json",old.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));h.assertTrue(CityTrade.load(tag,h.getLevel().registryAccess()).state.familyBudgets.isEmpty(),"Old saves initialize empty budgets without touching accounts");}h.succeed();}
 @GameTest(template="empty") public static void smallSurplusesAccumulateWithoutCreatingCoins(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=f.t.state.businesses.values().stream().filter(v->v.kind.equals("baker")).findFirst().orElseThrow();var family=f.r.state.families.get(f.r.state.people.get(b.owner).family);FamilyBudget.daily(f.s,family,0);long money=f.t.money(f.s);for(int day=1;day<=10;day++){CityTrade.pay(f.s,CityEconomy.treasury(f.city.id),CityEconomy.person(b.owner),5,"TEST_REAL_INCOME");FamilyBudget.daily(f.s,family,day);}var p=FamilyBudget.policy(f.s,family);h.assertTrue(p.allowance>5&&p.allowance>p.surplus*.75&&f.t.money(f.s)==money,"Unspent small credits persist across days; only actual existing money moves");long cash=FamilyBudget.owned(f.s,family);CityTrade.pay(f.s,CityEconomy.person(b.owner),b.account,2,"TEST_SELF_PURCHASE");FamilyBudget.spent(f.s,family,2,0);h.assertTrue(FamilyBudget.owned(f.s,family)==cash&&p.spent==0&&p.used==2,"Internal purchase consumes quota but creates no external spending or measured income");}h.succeed();}
 @GameTest(template="empty") public static void fullRawPantryStillReservesRealProcessingMoney(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var family=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();for(var s:f.r.stocks(family.id)){s.wheat=s.bread=0;RuralMeat.clear(s);}RuralRules.put(f.r.stocks(family.id),false,30);var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();home.secondary=true;f.t.state.households.put(family.id,home);h.assertTrue(FamilyBudget.processing(f.s,family)>0&&FamilyBudget.reserve(f.s,family)==FamilyBudget.processing(f.s,family),"Raw grain covers ingredients, but does not replace the money needed for residual paid processing");home.processor=null;int portions=DataCityRules.foodReserve(RuralRules.demand(family,f.r.state.people),3);h.assertTrue(FamilyBudget.reserve(f.s,family)==portions*(long)f.t.quote(f.s,family.city,1,f.r.state.simulationTicks),"A full raw pantry cannot replace edible food when no processor is usable");}h.succeed();}
 @GameTest(template="empty") public static void internalTransfersCannotFundLuxuryAndMembersShareLimit(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=f.t.state.businesses.values().stream().filter(v->v.kind.equals("baker")).findFirst().orElseThrow();var family=f.r.state.families.get(f.r.state.people.get(b.owner).family);for(var s:f.r.stocks(family.id)){s.wheat=s.bread=0;RuralMeat.clear(s);}RuralRules.put(f.r.stocks(family.id),true,30);FamilyBudget.daily(f.s,family,0);CityTrade.pay(f.s,b.account,CityEconomy.person(b.owner),10,"TEST_INTERNAL");FamilyBudget.daily(f.s,family,1);h.assertTrue(FamilyBudget.policy(f.s,family).surplus==0,"Own company transfer is not household income");CityTrade.pay(f.s,CityEconomy.treasury(f.city.id),CityEconomy.person(b.owner),20,"TEST_REAL_INCOME");FamilyBudget.daily(f.s,family,2);h.assertTrue(FamilyBudget.spare(f.s,family,b.owner)==1,"Measured net cash surplus enables a bounded optional purchase");FamilyBudget.spent(f.s,family,1);h.assertTrue(FamilyBudget.spare(f.s,family,b.owner)==0,"Family members cannot each reuse the same optional budget");}h.succeed();}
}




